// THE LAB'S CREATURES: their pictures, generated by code like everything in
// textures.js (whose helpers these use). The behaviour is in creatures.js.
//
// THE LURCHER: a hunched, man-sized mutant, pale and stitched together, its
// small head sunk between massive shoulders. Its right arm is the experiment
// that took: swollen, greenish, with bigger claws. Its eyes glow, so in a
// dark corner you see them before you see it.
//
// Same layout as a robot (ROBOT_FRAMES): frames[view][pose], 64x64, feet on
// the bottom row, the torso across row 32 where shots land (combat.js).
// Poses: stand, walk1, walk2, and two attack poses seen only from the front:
//   rear    the wind-up: reared up, arms raised, mouth open. Your warning.
//   lunge   the lunge: crouched, arms flung wide and forward

const FLESH = [178, 160, 146];
const FLESH_DARK = [104, 86, 80];
const MUTANT = [132, 150, 98];      // the swollen arm
const VEIN = [92, 118, 76];
const CLAW = [222, 214, 188];
const MAW = [74, 14, 20];
const STAPLE = [60, 64, 72];
const CREATURE_EYE = [150, 255, 90];
const ICHOR = [70, 116, 40];

// Mottled skin: the base colour, unevenly blotched, with the odd green vein.
function skin(colour, x, y, shade, seed) {
  // Veins only in a few patches of skin, or they break up into speckle.
  const vein = noise(x >> 3, y >> 3, seed + 3) > 0.7 && Math.abs(Math.sin(x * 0.55 + y * 0.32 + 4 * noise(x >> 3, y >> 3, seed))) < 0.12;
  const blotch = 0.9 + 0.12 * noise(x >> 2, y >> 2, seed + 1) + 0.04 * noise(x, y, seed + 2);
  return brighten(vein ? VEIN : colour, shade * blotch);
}

// Is (dx, y) inside the ellipse at (cx, cy) with radii rx, ry? Returns how
// far out from the centre it is (0 middle, 1 edge), or null if outside.
function inEllipse(dx, y, cx, cy, rx, ry) {
  const ux = (dx - cx) / rx, uy = (y + 0.5 - cy) / ry;
  const r = ux * ux + uy * uy;
  return r < 1 ? Math.sqrt(r) : null;
}

// One arm: shoulder -> elbow -> hand, a knot of a fist, and three claws.
// The forearm is thicker than the upper arm (that's where the swipe comes
// from). `big` is the mutant arm. clawsUp points the claws upwards (reared).
function lurcherArm(x, y, dx, shoulder, elbow, hand, big, clawsUp, shade) {
  const s = big ? 1.35 : 1;
  const colour = big ? MUTANT : FLESH;
  const r = 3.6 * s;
  for (const k of [-1, 0, 1]) {
    const tipY = clawsUp ? hand[1] - r - 5 * s : hand[1] + r + 5 * s;
    const baseY = clawsUp ? hand[1] - r * 0.5 : hand[1] + r * 0.5;
    const d = segmentDistance(dx, y, hand[0] + k * 2.2 * s, baseY, hand[0] + k * 3.4 * s, tipY);
    if (d < 1.1) return brighten(CLAW, shade * (1.15 - 0.3 * d));
  }
  const fist = inEllipse(dx, y, hand[0], hand[1], r, r);
  if (fist !== null) return skin(colour, x, y, shade * (1.1 - 0.45 * fist), 71);
  for (const [a, b, w] of [[elbow, hand, 3.2 * s], [shoulder, elbow, 2.8 * s]]) {
    const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
    if (d < w) return skin(colour, x, y, shade * (1.1 - 0.5 * d / w), 72);
  }
  return null;
}

// A short, bowed leg and a broad foot with toe claws.
function lurcherLeg(x, y, dx, hip, knee, ankle, shade) {
  if (y >= ankle[1] && y < ankle[1] + 4 && Math.abs(dx - ankle[0]) < 5) {
    if (y === ankle[1] + 3 && (Math.floor(dx - ankle[0] + 5) % 3) === 0) return brighten(CLAW, shade);
    return skin(FLESH_DARK, x, y, shade, 73);
  }
  for (const [a, b, w] of [[hip, knee, 4], [knee, ankle, 3]]) {
    const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
    if (d < w) return skin(FLESH_DARK, x, y, shade * (1.2 - 0.5 * d / w), 74);
  }
  return null;
}

// From the front or the back. From the front its right (mutant) arm is on
// YOUR left; from behind, on your right.
function lurcherFrontBackShape(view, pose) {
  const front = view === 'front';
  const drop = pose === 'lunge' ? 3 : 0; // it crouches into the lunge
  const open = pose === 'rear' || pose === 'lunge';
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const yy = y - drop;

    // Arms first: they're in front of the body or out to the sides.
    for (const side of [-1, 1]) {
      const big = front ? side < 0 : side > 0;
      const sway = pose === 'walk1' ? side * 2 : pose === 'walk2' ? -side * 2 : 0;
      let shoulder = [side * 12, 23 + drop], elbow, hand;
      if (pose === 'rear') { elbow = [side * 21, 13]; hand = [side * 17, 7]; }
      else if (pose === 'lunge') { elbow = [side * 22, 29]; hand = [side * 25, 37]; }
      else { elbow = [side * 18, 37]; hand = [side * 18 + sway * 0.5, 50 + Math.abs(sway) * 0.5]; }
      const arm = lurcherArm(x, y, dx, shoulder, elbow, hand, big, pose === 'rear', 1);
      if (arm) return arm;
    }

    // The head, sunk low between the shoulders.
    const head = inEllipse(dx, yy, 0, 19, 5.5, 5);
    if (head !== null) {
      if (front) {
        const eyeRow = yy >= 17 && yy < 19;
        if (eyeRow && Math.abs(dx) > 1.2 && Math.abs(dx) < 4) {
          return glowing(open ? [230, 255, 200] : CREATURE_EYE); // rearing, the eyes flare
        }
        const mouthTop = 21, mouthBottom = open ? 25 : 23;
        if (yy >= mouthTop && yy < mouthBottom && Math.abs(dx) < (open ? 4 : 3)) {
          const teeth = (yy === mouthTop || (open && yy === mouthBottom - 1)) && Math.floor(dx + 8) % 2 === 0;
          return teeth ? CLAW : MAW;
        }
      } else if (yy >= 15 && yy < 22 && Math.abs(dx) < 0.8) {
        return brighten(FLESH_DARK, 0.9); // a ridge over the skull
      }
      return skin(FLESH, x, y, 1.1 - 0.4 * head, 75);
    }

    // The torso: a hump of shoulder, narrowing to the waist.
    if (yy >= 17 && yy < 45) {
      const halfW = yy < 24 ? 9 + (yy - 17) * 0.85 : 15 - (yy - 24) * 0.3;
      if (Math.abs(dx) < halfW) {
        if (front) {
          // A surgical scar down the chest, held with staples.
          if (yy >= 26 && yy < 42 && yy % 3 === 0 && Math.abs(dx) < 2.5) return STAPLE;
          if (yy >= 26 && yy < 42 && Math.abs(dx) < 0.6) return brighten(MAW, 1.4);
        } else {
          // The spine, a row of knobs, and three feeding ports beside it,
          // still glowing with whatever they pumped into it.
          if (Math.abs(dx) < 2 && yy >= 20 && yy < 43 && yy % 4 < 3) return brighten(CLAW, 0.8 - 0.15 * Math.abs(dx));
          for (const py of [25, 32, 39]) {
            const p = Math.hypot(dx - 6, yy + 0.5 - py);
            if (p < 1.5) return glowing(CREATURE_EYE);
            if (p < 2.5) return STAPLE;
          }
        }
        return skin(FLESH, x, y, roundShade(dx / halfW), 76);
      }
    }

    // Legs: the stepping one lifts its foot.
    for (const side of [-1, 1]) {
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      const leg = lurcherLeg(x, y, dx, [side * 6, 43 + drop], [side * 10, 52 + drop * 0.5 - lift], [side * 8, 59 - lift], 1);
      if (leg) return leg;
    }
    return null;
  };
}

// Side on, facing right: the hunch shows here, head thrust forward. The near
// arm hangs in front of the body; the swollen far arm pokes out behind it.
function lurcherSideShape(pose) {
  const swing = pose === 'walk1' ? 4 : pose === 'walk2' ? -4 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;

    const near = lurcherArm(x, y, dx, [3, 24], [7 + swing * 0.3, 38], [11 + swing * 0.6, 50], false, false, 1);
    if (near) return near;

    const head = inEllipse(dx, y, 11, 24, 5.5, 4.5);
    if (head !== null) {
      if (dx >= 12.5 && dx < 15 && y >= 22 && y < 24) return glowing(CREATURE_EYE);
      if (dx >= 12 && dx < 16.5 && y === 26) return MAW;
      return skin(FLESH, x, y, 1.1 - 0.4 * head, 77);
    }

    // The hunched back, and the narrower hips under it.
    const hump = inEllipse(dx, y, -2, 29, 11.5, 10.5);
    if (hump !== null) {
      // Knobs of spine along the top of the back.
      if (dx < 2 && hump > 0.82 && y < 28 && Math.floor(dx + 20) % 4 < 2) return brighten(CLAW, 0.8);
      return skin(FLESH, x, y, 1.15 - 0.45 * hump, 78);
    }
    const hips = inEllipse(dx, y, -4, 38, 8, 6.5);
    if (hips !== null) return skin(FLESH, x, y, 0.85 - 0.3 * hips, 82);

    const far = lurcherArm(x, y, dx, [-3, 24], [-1 - swing * 0.3, 38], [3 - swing * 0.6, 50], true, false, 0.6);
    if (far) return far;

    for (const [s, shade] of [[swing, 1], [-swing, 0.6]]) {
      const leg = lurcherLeg(x, y, dx, [-6, 41], [1 + s * 0.6, 50], [-4 + s, 59], shade);
      if (leg) return leg;
    }
    return null;
  };
}

function makeLurcherFrames() {
  const bake = (shape) => makeTexture(FLESH, shape);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2') });
  const front = (pose) => bake(lurcherFrontBackShape('front', pose));
  return {
    front: { ...poses(front), rear: front('rear'), lunge: front('lunge') },
    back:  poses((pose) => bake(lurcherFrontBackShape('back', pose))),
    right: poses((pose) => bake(lurcherSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(lurcherSideShape(pose), true))),
  };
}

// A dead lurcher: a slumped heap of flesh in a pool of green ichor, the
// mutant arm flung out, claws up.
function makeLurcherCorpse() {
  return makeTexture(FLESH, (x, y) => {
    const dx = x + 0.5 - 32;
    const arm = lurcherArm(x, y, dx, [6, 52], [16, 55], [24, 52], true, true, 0.85);
    if (arm) return arm;
    if (y >= 46) {
      const halfW = 11 + (y - 46) * 0.9;
      if (Math.abs(dx) < halfW && y < 61) {
        if (y >= 51 && y < 53 && dx > -9 && dx < -6) return [40, 60, 30]; // an eye, gone dark
        return skin(FLESH, x, y, 0.55 + 0.4 * noise(x >> 2, y >> 1, 79), 80);
      }
    }
    if (y >= 59 && Math.abs(dx) < 26 - (63 - y) * 2) return brighten(ICHOR, 0.8 + 0.3 * noise(x, y, 81));
    return null;
  });
}

ROBOT_FRAMES.lurcher = makeLurcherFrames();
// What each type leaves behind (enemies.js). Robots leave the robot wreck.
const CORPSE_TEXTURES = { lurcher: makeLurcherCorpse() };
